declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionSnippetVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;

trait SnippetVersionSnippetAccessor
{
    private SnippetVersionSnippetVO $_snippet;
    public function getSnippet(): SnippetRef
    {
        return $this->_snippet->value();
    }
    public function snippet(): SnippetVersionSnippetVO
    {
        return $this->_snippet;
    }
    public function isSnippetChanged(?self $original = null): bool
    {
        return !$this->_snippet->equals($original?->_snippet);
    }
    public function withSnippet(SnippetVersionSnippetVO|SnippetRef $snippet): self
    {
        $copy = clone $this;
        $copy->_snippet = SnippetVersionSnippetVO::from($snippet);
        return $copy;
    }
}
